INSERT INTO dbo.qc_fin_spec_head ([id], [单据编号], [单据日期], [文件编号], [文件名称], [版本版次], [管控状态], [发行日期], [工单号], [报工单号], [产品编码], [产品名称], [规格型号], [批次号], [目的], [范围], [职责和权限], [取样要求], [工作程序], [制定], [审核], [核准], [备注], [审核人], [审核时间], [asp_user1], [asp_time1], [asp_user2], [asp_time2], [asp_cancel], [单据状态]) VALUES (7, N'CPJY-DEMO-0001', '2026-10-09', N'YJ-Q-125', N'Y料原料及成品检验规范', N'A0', N'受控', '2026-10-09', NULL, NULL, NULL, NULL, NULL, NULL, N'明确来料检验的工作方式、方法及控制流程，确保来料品质满足规范要求，并能有效根据流程实施控制。', N'适用于银嘉Y料原料及成品的质量检验工作。', N'本规范的实施者是品质部，品质部严格落实本规范，对实施过程及检验结果负责，并直接向总经理汇报。', N'4.1 每50kg原料取样1个，每个样品200g；4.2 每50kg成品取样1个，每个样品200g', N'原料仓库收货后即通知品质部进行来料检验，品质部根据本规范进行检验作业，并填写《来料检验报告》，如果检验合格，则通知仓管将来料入库，如果检验不合格，则填写《来料品质问题反馈单》，发给采购部，由采购部推动供应商解决问题。', NULL, NULL, NULL, N'格式示例(8 份受控文件归纳的统一骨架);正式使用请新建并填写本单位内容。', NULL, NULL, N'migration', '2026-10-10 13:47:20.8257664', NULL, NULL, N'N', N'草稿');
